def _collect_free_vars(expr: z3.ExprRef) -> dict[str, z3.ExprRef]:
    """Extract free variables (uninterpreted constants) from a Z3 expression."""
    seen: set[int] = set()
    result: dict[str, z3.ExprRef] = {}

    def _visit(e: z3.ExprRef) -> None:
        eid = e.get_id()
        if eid in seen:
            return
        seen.add(eid)
        if z3.is_const(e) and e.decl().kind() == z3.Z3_OP_UNINTERPRETED:
            s = e.sort()
            if s in (z3.IntSort(), z3.RealSort(), z3.BoolSort()):
                result[str(e)] = e
        for i in range(e.num_args()):
            _visit(e.arg(i))

    _visit(expr)
    return result


